2358	            constexpr int HDQK = (HD < 128) ? 128 : HD;   // K/Q 128-wide (koff8 row*128); see fp8 kernel
2359	            int smem_p = (int)(QBUF * CTA_M * HDQK + STAGES * CTA_N * HDQK + STAGES * HDV * CTA_N + CTA_M * CTA_N
2360	                               + STAGES * CTA_N * HDV)
2361	                         + (3 * STAGES + 2 * QBUF + 2 * SDEPTH) * (int)sizeof(uint64_t) + SDEPTH * (int)sizeof(int);
