263	// Combined causal + key-length mask. r=0->qlo (row_lo), r=1->qhi (row_hi). col indices: s[c*4+r*2+p].
264	// Cheap causal/bounds-only mask (hot path: no sliding window).
265	template <int CN = CTA_N>
266	__device__ __forceinline__ void pf_mask(float (&s)[CN/2], int col0, int qlo, int qhi, int seqlen_k, int causal, int tg) {
267	    // Fast-out for fully-visible tiles (the common case in causal prefill: only the diagonal tile of
268	    // each work item is partially masked, every interior tile is entirely below the diagonal and within
269	    // seqlen_k). kmax = col0+CN-1 is the largest key index this CTA's tile spans; if it is < seqlen_k and
270	    // <= the smaller query position (qlo), no element of either row is masked -> skip the per-element ALU
271	    // that otherwise sits on the QK->next-QK critical path (stealing tensor-pipe issue slots while PV is
272	    // in flight). Conservative (tile-global kmax) so the branch is uniform across the warpgroup.
273	    const int kmax = col0 + CN - 1;
274	    if (kmax < seqlen_k && (!causal || kmax <= qlo)) return;
275	#pragma unroll
276	    for (int c = 0; c < CN / 8; ++c) {
277	        int k0 = col0 + 8 * c + 2 * tg;
278	        if (k0     >= seqlen_k || (causal && k0     > qlo)) s[c*4+0] = -INFINITY;
279	        if (k0 + 1 >= seqlen_k || (causal && k0 + 1 > qlo)) s[c*4+1] = -INFINITY;
280	        if (k0     >= seqlen_k || (causal && k0     > qhi)) s[c*4+2] = -INFINITY;
281	        if (k0 + 1 >= seqlen_k || (causal && k0 + 1 > qhi)) s[c*4+3] = -INFINITY;
282	    }
283	}
284	// Windowed mask (sliding window): valid <=> key<seqlen_k && !(causal&&key>qpos) &&
285	//   !(win_l>=0&&key<qpos-win_l) && !(win_r>=0&&key>qpos+win_r). Collapsed into a per-row valid key
286	// range [lo, hi] (inclusive) computed ONCE, then 2 comparisons/element instead of 4 conditions/element.
287	// The mask sits on the critical path between the QK wgmma result and the next wgmma issue, so halving
288	// its ALU recovers tensor-pipe utilization that softcap/SWA otherwise lose (NCU: tensor 23%->~).
289	template <int CN = CTA_N>
290	__device__ __forceinline__ void pf_mask_win(float (&s)[CN/2], int col0, int qlo, int qhi, int seqlen_k,
291	                                            int causal, int win_l, int win_r, int tg, int lpad = 0) {
292	    constexpr int NEG = -0x40000000;                                  // -inf sentinel for "no left bound"
293	    int lo0 = (win_l >= 0) ? (qlo - win_l) : NEG;
294	    int lo1 = (win_l >= 0) ? (qhi - win_l) : NEG;
295	    // cache_leftpad: keys [0, lpad) are ignored -> absolute lower bound on the valid key range (folds in
296	    // alongside the relative sliding-window left bound; lpad==0 leaves lo0/lo1 untouched, zero overhead).
297	    if (lpad > 0) { if (lpad > lo0) lo0 = lpad; if (lpad > lo1) lo1 = lpad; }
298	    int hi0 = seqlen_k - 1, hi1 = seqlen_k - 1;                       // upper bound folds in seqlen_k
299	    if (causal)     { if (qlo < hi0) hi0 = qlo;        if (qhi < hi1) hi1 = qhi; }
300	    if (win_r >= 0) { int t = qlo + win_r; if (t < hi0) hi0 = t;  t = qhi + win_r; if (t < hi1) hi1 = t; }
301	    // Fast-out for fully-visible tiles (same lever as pf_mask): if every key index this tile spans lies
302	    // within the most-restrictive [lo,hi] of both rows, nothing is masked -> skip the per-element ALU on
303	    // the QK->next-QK critical path. lo = max(lo0,lo1) (tightest left), hi = min(hi0,hi1) (tightest right).
304	    const int kmax = col0 + CN - 1;
305	    const int lo = lo0 > lo1 ? lo0 : lo1, hi = hi0 < hi1 ? hi0 : hi1;
306	    if (col0 >= lo && kmax <= hi) return;
307	#pragma unroll
308	    for (int c = 0; c < CN / 8; ++c) {
309	        int k0 = col0 + 8 * c + 2 * tg;
310	        if (k0     < lo0 || k0     > hi0) s[c*4+0] = -INFINITY;
311	        if (k0 + 1 < lo0 || k0 + 1 > hi0) s[c*4+1] = -INFINITY;
312	        if (k0     < lo1 || k0     > hi1) s[c*4+2] = -INFINITY;
313	        if (k0 + 1 < lo1 || k0 + 1 > hi1) s[c*4+3] = -INFINITY;
314	    }
315	}
